ght(mm)\"\') AS HEIGHT_MM, JSON_VALUE(_airbyte_data, \'$.\"Sale Order Item Status\"\') AS SALE_ORDER_ITEM_STATUS, JSON_VALUE(_airbyte_data, \'$.\"TCS Amount\"\') AS TCS_AMOUNT, JSON_VALUE(_airbyte_data, \'$.\"Channel Shipping\"\') AS CHANNEL_SHIPPING, JSON_VALUE(_airbyte_data, \'$.\"Billing Address Country\"\') AS BILLING_ADDRESS_COUNTRY, JSON_VALUE(_airbyte_data, \'$.\"Require Customization\"\') AS REQUIRE_CUSTOMIZATION, JSON_VALUE(_airbyte_data, \'$.\"Category\"\') AS CATEGORY, JSON_VALUE(_airbyte_data, \'$.\"Voucher Code\"\') AS VOUCHER_CODE, JSON_VALUE(_airbyte_data, \'$.\"On Hold\"\') AS ON_HOLD, JSON_VALUE(_airbyte_data, \'$.\"Gift Wrap\"\') AS GIFT_WRAP, JSON_VALUE(_airbyte_data, \'$.\"Fulfillment TAT\"\') AS FULFILLMENT_TAT, JSON_VALUE(_airbyte_data, \'$.\"Item SKU Code\"\') AS ITEM_SKU_CODE, JSON_VALUE(_airbyte_data, \'$.\"Adjustment In Discount\"\') AS ADJUSTMENT_IN_DISCOUNT, JSON_VALUE(_airbyte_data, \'$.\"CESS Rate\"\') AS CESS_RATE, JSON_VALUE(_airbyte_data, \'$.\"Return Reason\"\') AS RETURN_REASON, JSON_VALUE(_airbyte_data, \'$.\"Shipping Address Latitude\"\') AS SHIPPING_ADDRESS_LATITUDE, JSON_VALUE(_airbyte_data, \'$.\"CGST\"\') AS CGST, JSON_VALUE(_airbyte_data, \'$.\"Return Date\"\') AS RETURN_DATE, JSON_VALUE(_airbyte_data, \'$.\"Vendor Batch Number\"\') AS VENDOR_BATCH_NUMBER, JSON_VALUE(_airbyte_data, \'$.\"IGST\"\') AS IGST, JSON_VALUE(_airbyte_data, \'$.\"Combination Identifier\"\') AS COMBINATION_IDENTIFIER, JSON_VALUE(_airbyte_data, \'$.\"Item Type EAN\"\') AS ITEM_TYPE_EAN, JSON_VALUE(_airbyte_data, \'$.\"UTGST Rate\"\') AS UTGST_RATE, JSON_VALUE(_airbyte_data, \'$.\"IMEI\"\') AS IMEI, JSON_VALUE(_airbyte_data, \'$.\"Billing Address Phone\"\') AS BILLING_ADDRESS_PHONE, JSON_VALUE(_airbyte_data, \'$.\"Shipping Address Longitude\"\') AS SHIPPING_ADDRESS_LONGITUDE, JSON_VALUE(_airbyte_data, \'$.\"Display Order Code\"\') AS DISPLAY_ORDER_CODE, JSON_VALUE(_airbyte_data, \'$.\"Shipping Address Line 1\"\') AS SHIPPING_ADDRESS_LINE_1, JSON_VALUE(_