PARSE_TIMESTAMP( \'%Y-%m-%d %H:%M:%S\', NULLIF(Order_Date_as_dd_mm_yyyy_hh_MM_ss, \'\') ) ) AS order_date, FORMAT_TIMESTAMP( \'%Y-%m-%dT%H:%M:%S\', SAFE.PARSE_TIMESTAMP( \'%Y-%m-%d %H:%M:%S\', NULLIF(Shipping_Package_Creation_Date, \'\') ) ) AS shipping_package_creation_date, SAFE_CAST(Shipping_Charges AS FLOAT64) AS shipping_price, 1 AS suborder_quantity, SAFE_CAST(discount AS FLOAT64) AS discount, SAFE_CAST(Tax_Value AS FLOAT64) AS tax, SAFE_CAST(fi.Selling_Price AS FLOAT64) AS selling_price, Shipping_Package_Code AS shippingPackageCode, Shipping_Package_Status_Code AS shippingPackageStatus, Sale_Order_Item_Code AS SaleOrderItemCode, Sale_Order_Item_Code AS Sales_Order_Item_ID, Tracking_Number AS AWB, FACILITY AS Warehouse_Name, CASE WHEN COD = \'0\' THEN \'Prepaid\' ELSE \'COD\' END AS Payment_Mode, CASE WHEN COD = \'0\' THEN \'Prepaid\' ELSE \'COD\' END AS Payment_Method, Shipping_Courier AS Courier, Shipping_Courier_Status AS shipping_status, Shipping_Tracking_Status AS shipping_tracking_status, 1 AS shippedQuantity, FORMAT_TIMESTAMP( \'%Y-%m-%dT%H:%M:%S\', SAFE.PARSE_TIMESTAMP( \'%Y-%m-%d %H:%M:%S\', NULLIF(Dispatch_Date, \'\') ) ) AS dispatch_date, FORMAT_TIMESTAMP( \'%Y-%m-%dT%H:%M:%S\', SAFE.PARSE_TIMESTAMP( \'%Y-%m-%d %H:%M:%S\', NULLIF(EWayBill_Date, \'\') ) ) AS ewaybill_date, FORMAT_TIMESTAMP( \'%Y-%m-%dT%H:%M:%S\', SAFE.PARSE_TIMESTAMP( \'%Y-%m-%d %H:%M:%S\', NULLIF(Delivery_Time, \'\') ) ) AS delivery_date, FORMAT_TIMESTAMP( \'%Y-%m-%dT%H:%M:%S\', SAFE.PARSE_TIMESTAMP( \'%Y-%m-%d %H:%M:%S\', NULLIF(Return_Date, \'\') ) ) AS return_date, FORMAT_TIMESTAMP( \'%Y-%m-%dT%H:%M:%S\', SAFE.PARSE_TIMESTAMP( \'%Y-%m-%d %H:%M:%S\', NULLIF(Reverse_Pickup_Created_Date, \'\') ) ) AS reverse_pickup_date, return_reason, FORMAT_TIMESTAMP( \'%Y-%m-%dT%H:%M:%S\', SAFE.PARSE_TIMESTAMP( \'%Y-%m-%d %H:%M:%S\', NULLIF(Fulfillment_TAT, \'\') ) ) AS fulfillment_tat, Reverse_Pickup_Code AS reverse_pickup_code, Return_Remarks AS return_remarks, Reverse_Pickup_Reason AS reverse_pickup_reason, CASE WHEN Return_Date IS NOT NULL AND TRIM(Return_Date) <> \'\' AND LOWER(TRIM(Return_Date)) <> \'null\' THEN 1 ELSE 0 END AS return_flag, CASE WHEN Return_Date IS NOT NULL AND TRIM(Return_Date) <> \'\' AND LOWER(TRIM(Return_Date)) <> \'null\' THEN 1 ELSE 0 END AS return_quantity, CASE WHEN Return_Date IS NOT NULL AND TRIM(Return_Date) <> \'\' AND LOWER(TRIM(Return_Date)) <> \'null\' THEN SAFE_CAST(fi.Selling_Price AS FLOAT64) ELSE 0 END AS return_sales, CASE WHEN LOWER(Sale_Order_Status) LIKE \'%cancel%\' OR LOWER(Shipping_Courier_Status) LIKE \'%cancel%\' THEN 1 ELSE 0 END AS cancelled_quantity, COALESCE(sk.product_name, fi.Item_Type_Name, fi.SKU_Name) AS PRODUCT_NAME_Final, COALESCE(sk.category, fi.category) AS Product_category, CAST(NULL AS STRING) AS mapped_sub_category, COALESCE(sk.sku_code, fi.Item_SKU_Code) AS commonsku, CAST(NULL AS FLOAT64) AS cogs, CAST(NULL AS FLOAT64) AS sku_mrp, CAST(NULL AS STRING) AS brand, CAST(NULL AS FLOAT64) AS tax_rate, CAST(NULL AS FLOAT64) AS packaging_cost, sk.sku_code as SKU_Code, url, ROW_NUMBER() OVER ( PARTITION BY Display_Order_Code, Sale_Order_Item_Code ORDER BY SAFE.PARSE_TIMESTAMP( \'%Y-%m-%d %H:%M:%S\', NULLIF(updated, \'\') ) DESC ) AS rw FROM MAPLEMONK.rar_unicommerce_get_sale_orders_data_flattened fi LEFT JOIN ( SELECT * FROM `rainandrainbow-wh.maplemonk.RAR_SKU_MASTER` QUALIFY ROW_NUMBER() OVER ( PARTITION BY UPPER(SKU_CODE) ORDER BY SKU_CODE ) = 1 ) sk ON UPPER(sk.SKU_CODE) = UPPER(fi.Item_SKU_Code) ) WHERE rw = 1;",
